import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { registerUser } from "../Features/UserSlice";
import { useNavigate, Link } from "react-router-dom";
import "../Styles/UserRegister.css";
import registerImg from "../Images/login-side.png";

const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isLoading, isError, isSuccess } = useSelector((state) => state.users);

  // ✅ نفس أسلوب الأستاذة
  const [name, setname] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [major, setMajor] = useState("");
  const [age, setAge] = useState("");

  const handleRegister = () => {
    const userData = {
      name,
      email,
      password,
      major,
      age,
    };

    dispatch(registerUser(userData));
  };

  // ✅ التنقل بعد النجاح أو الفشل
  useEffect(() => {
    if (isSuccess) {
      alert("Student Registered ✅");

      // 🟢 نفس أسلوب الأستاذة في Login: نحفظ بيانات المستخدم والدور
      const storedUser = {
        name,
        email,
        major,
        age,
        role: "student",
      };
      localStorage.setItem("loggedUser", JSON.stringify(storedUser));
      localStorage.setItem("role", "student");

      navigate("/user-profile");
    } else if (isError) {
      alert("❌ Registration failed. Try again.");
    }
  }, [isSuccess, isError, navigate]);

  return (
    <div className="register-page">
      <div className="register-container">
        {/* LEFT SIDE (FORM) */}
        <div className="register-form">
          <h1 className="reg-title">
            Create your <span className="accent">account</span>
          </h1>
          <p className="reg-sub">Please fill in your details to continue</p>

          <div className="role-switch">
            <Link to="/user-register" className="role-btn active">
              Student
            </Link>
            <Link to="/company-register" className="role-btn">
              Company
            </Link>
          </div>

          <form>
            <label>Full Name</label>
            <input
              type="text"
              placeholder="Your name"
              value={name}
              onChange={(e) => setname(e.target.value)}
            />

            <label>Email</label>
            <input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />

            <label>Password</label>
            <input
              type="password"
              placeholder="********"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />

            <div className="row-flex">
              <div className="col-half">
                <label>Major</label>
                <select
                  value={major}
                  onChange={(e) => setMajor(e.target.value)}
                >
                  {MAJORS.map((m, i) => (
                    <option key={i} value={m}>
                      {m === "" ? "Select your major" : m}
                    </option>
                  ))}
                </select>
              </div>

              <div className="col-half">
                <label>Age</label>
                <input
                  type="number"
                  min="17"
                  max="45"
                  value={age}
                  onChange={(e) => setAge(e.target.value)}
                />
              </div>
            </div>

            <button
              type="button"
              className="reg-btn"
              onClick={handleRegister}
              disabled={isLoading}
            >
              {isLoading ? "Registering..." : "Sign up"}
            </button>

            {isError && <p className="error">Registration failed ❌</p>}
            {isSuccess && <p className="success">Registered successfully ✅</p>}

            <p className="login-text">
              Already have an account?{" "}
              <Link to="/login" className="login-link">
                Log in now!
              </Link>
            </p>
          </form>
        </div>

        {/* RIGHT SIDE (IMAGE) */}
        <div className="register-image">
          <img src={registerImg} alt="Registration illustration" />
        </div>
      </div>
    </div>
  );
};

export default UserRegister;
